#!/usr/bin/env python """ Export SBERT model to TensorFlow Lite format for mobile deployment. Uses sentence-transformers for simpler embedding generation. """ import os import tensorflow as tf import numpy as np from sentence_transformers import SentenceTransformer # Create output directory os.makedirs("assets/models", exist_ok=True) # Load a small sentence transformer model model_name = "distilbert-base-uncased" print(f"Loading model: {model_name}") sbert_model = SentenceTransformer(model_name) # Get the transformer model and tokenizer bert_model = sbert_model[0] tokenizer = sbert_model.tokenizer # Build a model that takes text input and outputs embeddings class SBERTEncoder(tf.Module): def __init__(self, bert_model, tokenizer): self.bert_model = bert_model self.tokenizer = tokenizer @tf.function(input_signature=[ tf.TensorSpec(shape=[None], dtype=tf.string), ]) def __call__(self, text_input): # Tokenize in Python and use tensor operations def encode_single(text): encoded = self.tokenizer( text.numpy().decode('utf-8'), max_length=128, padding='max_length', truncation=True, return_tensors='tf' ) return encoded['input_ids'], encoded['attention_mask'] input_ids, attention_mask = tf.py_function( func=encode_single, inp=[text_input], Tout=[tf.int32, tf.int32] ) input_ids.set_shape([None, 128]) attention_mask.set_shape([None, 128]) outputs = self.bert_model(input_ids, attention_mask=attention_mask) # Mean pooling embeddings = tf.reduce_mean(outputs.last_hidden_state, axis=1) return embeddings encoder = SBERTEncoder(bert_model, tokenizer) # Test the model with a sample input test_input = tf.constant(["hello world"]) test_output = encoder(test_input) print(f"Test output shape: {test_output.shape}") # Save as SavedModel saved_model_path = "assets/models/sbert_saved" tf.saved_model.save(encoder, saved_model_path) print(f"Saved SavedModel to {saved_model_path}") # Convert to TFLite converter = tf.lite.TFLiteConverter.from_saved_model(saved_model_path) converter.optimizations = [tf.lite.Optimize.DEFAULT] converter.target_spec.supported_types = [tf.float32] tflite_model = converter.convert() tflite_path = "assets/models/sbert.tflite" with open(tflite_path, 'wb') as f: f.write(tflite_model) print(f"Saved TFLite model to {tflite_path}") print(f"Model size: {os.path.getsize(tflite_path) / 1024 / 1024:.2f} MB")